from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np, json

smi = "c1ccccc1n2c(c3ccco3)nnc2-c4ccccn4"
mol = Chem.MolFromSmiles(smi)
mol = Chem.AddHs(mol)
AllChem.EmbedMolecule(mol, randomSeed=42)
AllChem.MMFFOptimizeMolecule(mol)
coords = mol.GetConformer().GetPositions()

ri = mol.GetRingInfo()
triaz_N = pyr_N = None
for ring in ri.AtomRings():
    ringset = set(ring)
    if len(ring)==5:
        ns = [a for a in ring if mol.GetAtomWithIdx(a).GetSymbol()=="N"]
        if len(ns)==3:
            n4 = c3 = None
            for n in ns:
                for x in mol.GetAtomWithIdx(n).GetNeighbors():
                    if x.GetSymbol()=="C" and x.GetIsAromatic() and x.GetIdx() not in ringset:
                        n4 = n
            for a in ring:
                at = mol.GetAtomWithIdx(a)
                if at.GetSymbol()=="C":
                    for x in at.GetNeighbors():
                        if x.GetIdx() not in ringset and x.GetSymbol()=="N":
                            c3 = a; pyr_N = x.GetIdx()
            for x in mol.GetAtomWithIdx(c3).GetNeighbors():
                if x.GetSymbol()=="N" and x.GetIdx() in ringset and x.GetIdx()!=n4:
                    triaz_N = x.GetIdx()
print("triazole N2 idx:", triaz_N, "pyridine N idx:", pyr_N)
elems = [a.GetSymbol() for a in mol.GetAtoms()]
np.save("lig_coords.npy", coords)
with open("ligand.xyz","w") as f:
    f.write(str(len(elems))+"\nligand\n")
    for e,c in zip(elems, coords):
        f.write(f"{e} {c[0]:.6f} {c[1]:.6f} {c[2]:.6f}\n")
json.dump({"triaz_N":triaz_N,"pyr_N":pyr_N,"elems":elems}, open("lig_info.json","w"))
print("natoms", len(elems))
