import numpy as np, itertools
def rd(p):
    lines=open(p).read().splitlines()
    n=int(lines[0]); els=[];xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); els.append(t[0]); xyz.append([float(v) for v in t[1:4]])
    return els,np.array(xyz)
e,c=rd('complex_opt.xyz')
pairs={ (0,15):'Cu-N2a',(0,22):'Cu-Npy a',(0,49):'Cu-N2b',(0,56):'Cu-Npy b',(0,69):'Cu-O nit1',(0,73):'Cu-O nit2'}
for (i,j),n in pairs.items(): print(n, round(np.linalg.norm(c[i]-c[j]),3))
# angles
import math
def ang(i,j,k):
    v1=c[i]-c[j]; v2=c[k]-c[j]
    return math.degrees(math.acos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
print('N2a-Cu-Npyb (trans?)', round(ang(15,0,56),1), ' N2b-Cu-Npya', round(ang(49,0,22),1))
print('O-Cu-O', round(ang(69,0,73),1))
print('N2a-Cu-N2b', round(ang(15,0,49),1), 'Npya-Cu-Npyb', round(ang(22,0,56),1))
# min interfragment
def frag(i):
    if i==0: return 'Cu'
    if i<=34: return 'L1'
    if i<=68: return 'L2'
    return 'NIT'
worst={}
for i,j in itertools.combinations(range(len(c)),2):
    fi,fj=frag(i),frag(j)
    if fi==fj: continue
    d=np.linalg.norm(c[i]-c[j]); key=tuple(sorted((fi,fj)))
    if key not in worst or d<worst[key][0]: worst[key]=(d,i,j,e[i],e[j])
for k,v in sorted(worst.items()): print(k, round(v[0],2), v[3],v[1],v[4],v[2])
# intramolecular bad contacts (<0.9 A nonbonded)
bad=[(i,j,round(np.linalg.norm(c[i]-c[j]),2)) for i,j in itertools.combinations(range(len(c)),2) if np.linalg.norm(c[i]-c[j])<0.95]
print('bad contacts:',bad[:10])
